void Solver::bump_var(int var, double coeff) {
    double increment = var_inc * coeff;
    activity[var] += increment;

    // Dynamic decay: increase decay factor for high-activity vars
    double decay_factor = 1.0;
    if (activity[var] > 1e50) {
        decay_factor = 0.95;
    }
    var_inc *= decay_factor;

    // Prevent overflow with more gradual scaling
    if (activity[var] > 1e100) {
        double scale = 1e-50;
        for (int i = 1; i <= vars; i++) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Update heap if present
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
